/*
 * Generated by the /ship test coverage audit (pass 2).
 *
 * Value: protects=a render that times out or whose result key expired answers 503 with an actionable message,
 *   and a read result key is deleted; fails_when=the error mapping, the expired-key guard or the del is removed;
 *   why_new=no spec covered ConfluenceRenderClient; seam=none;
 *   no_claim=a real Redis/BullMQ round trip or perfana-report (bullmq and ioredis mocked; unit only)
 */
import { ServiceUnavailableException } from '@nestjs/common';
import { ConfluenceRenderClient } from './confluence-render.client';

const redisStore = { get: jest.fn(), del: jest.fn(), on: jest.fn(), disconnect: jest.fn() };
const waitUntilFinished = jest.fn();

jest.mock('ioredis', () => ({ __esModule: true, default: jest.fn(() => redisStore) }));
jest.mock('bullmq', () => ({
  Queue: jest.fn(() => ({ add: jest.fn(async () => ({ id: '7', waitUntilFinished })), close: jest.fn(async () => undefined) })),
  QueueEvents: jest.fn(() => ({ close: jest.fn(async () => undefined) })),
}));

const client = () => new ConfluenceRenderClient({ get: (_k: string, d: string) => d } as never);

beforeEach(() => {
  jest.clearAllMocks();
});

describe('ConfluenceRenderClient.render', () => {
  it('reads the result once and deletes its key', async () => {
    waitUntilFinished.mockResolvedValue({ resultKey: 'confluence-render:7' });
    redisStore.get.mockResolvedValue(JSON.stringify({ html: '<p>x</p>', images: ['AAA'] }));

    await expect(client().render('r1')).resolves.toEqual({ html: '<p>x</p>', images: ['AAA'] });
    expect(redisStore.get).toHaveBeenCalledWith('confluence-render:7');
    expect(redisStore.del).toHaveBeenCalledWith('confluence-render:7');
  });

  it('answers 503 naming perfana-report when the render job times out', async () => {
    waitUntilFinished.mockRejectedValue(new Error('Job wait render timed out before finishing, no finish notification arrived after 180000ms (id=7)'));

    const err = await client().render('r1').catch((e) => e);
    expect(err).toBeInstanceOf(ServiceUnavailableException);
    expect(err.message).toMatch(/did not render the charts in time.*perfana-report/);
    expect(redisStore.get).not.toHaveBeenCalled();
  });

  it('answers 503 when the rendered result expired before it was read', async () => {
    waitUntilFinished.mockResolvedValue({ resultKey: 'confluence-render:7' });
    redisStore.get.mockResolvedValue(null);

    await expect(client().render('r1')).rejects.toThrow(new ServiceUnavailableException('The rendered report expired before it could be published; try again'));
  });
});
